from __future__ import annotations

import re
from dataclasses import dataclass
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from pathlib import Path

import pytesseract
from PIL import Image, ImageOps
from openpyxl import Workbook, load_workbook

IMG_DIR = Path('/app/workspace/dataset/img')
OUT_PATH = Path('/app/workspace/stat_ocr.xlsx')

IMAGE_EXTS = {'.png', '.jpg', '.jpeg', '.webp', '.tif', '.tiff'}

PRIORITY_KEYWORD_GROUPS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL'],
]

EXCLUSION_KEYWORDS = [
    'SUBTOTAL',
    'SUB TOTAL',
    'TAX',
    'GST',
    'SST',
    'DISCOUNT',
    'CHANGE',
    'CASH TENDERED',
]

MONTHS = {
    'JAN': 1, 'JANUARY': 1,
    'FEB': 2, 'FEBRUARY': 2,
    'MAR': 3, 'MARCH': 3,
    'APR': 4, 'APRIL': 4,
    'MAY': 5,
    'JUN': 6, 'JUNE': 6,
    'JUL': 7, 'JULY': 7,
    'AUG': 8, 'AUGUST': 8,
    'SEP': 9, 'SEPT': 9, 'SEPTEMBER': 9,
    'OCT': 10, 'OCTOBER': 10,
    'NOV': 11, 'NOVEMBER': 11,
    'DEC': 12, 'DECEMBER': 12,
}


def _signal_score(text: str) -> int:
    return sum(ch.isalnum() for ch in text)


def ocr_image(img: Image.Image) -> str:
    variants: list[tuple[str, Image.Image, str]] = []
    variants.append(('baseline', img, '--oem 3 --psm 6'))

    gray = ImageOps.grayscale(img)
    gray = ImageOps.autocontrast(gray)
    variants.append(('gray_autocontrast', gray, '--oem 3 --psm 6'))
    variants.append(('gray_autocontrast_psm4', gray, '--oem 3 --psm 4'))

    best_text = ''
    best_score = -1

    for name, im, config in variants:
        text = pytesseract.image_to_string(im, lang='eng', config=config) or ''
        score = _signal_score(text)
        if score > best_score:
            best_text, best_score = text, score

        if name == 'baseline' and score >= 40:
            break

    return best_text


def _normalize_text(text: str) -> str:
    text = text.replace('\u2014', '-').replace('\u2013', '-')
    text = re.sub(r'[\t\r]+', ' ', text)
    return text


def _coerce_year(y: int) -> int:
    if y < 100:
        return 2000 + y if y <= 69 else 1900 + y
    return y


def _valid_date(d: date) -> bool:
    return date(1990, 1, 1) <= d <= date(2035, 12, 31)


def extract_date(text: str) -> str | None:
    text = _normalize_text(text)
    lines = [ln.strip() for ln in text.splitlines()]

    candidates: list[tuple[int, int, date]] = []  # (priority, char_index, date)

    def add_candidate(pri: int, idx: int, d: date):
        if _valid_date(d):
            candidates.append((pri, idx, d))

    full_text_upper = text.upper()

    numeric_pat = re.compile(r'\b(\d{1,2})[\-/\.](\d{1,2})[\-/\.](\d{2,4})\b')
    ymd_pat = re.compile(r'\b(\d{4})[\-/\.](\d{1,2})[\-/\.](\d{1,2})\b')
    month_pat = re.compile(
        r'\b(\d{1,2})\s*([A-Z]{3,9})\s*(\d{2,4})\b'
    )

    for m in ymd_pat.finditer(text):
        y, mo, da = int(m.group(1)), int(m.group(2)), int(m.group(3))
        try:
            add_candidate(1, m.start(), date(y, mo, da))
        except ValueError:
            pass

    for m in numeric_pat.finditer(text):
        a, b, y = int(m.group(1)), int(m.group(2)), _coerce_year(int(m.group(3)))
        # Deterministic dd/mm preference when ambiguous.
        if a > 12 and b <= 12:
            da, mo = a, b
        elif b > 12 and a <= 12:
            mo, da = a, b
        else:
            da, mo = a, b
        try:
            add_candidate(2, m.start(), date(y, mo, da))
        except ValueError:
            pass

    for m in month_pat.finditer(text.upper()):
        da = int(m.group(1))
        mon_s = m.group(2)
        y = _coerce_year(int(m.group(3)))
        mon = MONTHS.get(mon_s)
        if not mon:
            continue
        try:
            add_candidate(3, m.start(), date(y, mon, da))
        except ValueError:
            pass

    # Boost candidates that are on a line containing DATE
    for i, ln in enumerate(lines):
        if 'DATE' not in ln.upper():
            continue
        # search this line and the next line
        chunk = ln
        if i + 1 < len(lines):
            chunk += '\n' + lines[i + 1]
        base_idx = full_text_upper.find(ln.upper())
        if base_idx < 0:
            base_idx = 0
        for m in ymd_pat.finditer(chunk):
            y, mo, da = int(m.group(1)), int(m.group(2)), int(m.group(3))
            try:
                add_candidate(0, base_idx + m.start(), date(y, mo, da))
            except ValueError:
                pass
        for m in numeric_pat.finditer(chunk):
            a, b, y = int(m.group(1)), int(m.group(2)), _coerce_year(int(m.group(3)))
            if a > 12 and b <= 12:
                da, mo = a, b
            elif b > 12 and a <= 12:
                mo, da = a, b
            else:
                da, mo = a, b
            try:
                add_candidate(0, base_idx + m.start(), date(y, mo, da))
            except ValueError:
                pass
        for m in month_pat.finditer(chunk.upper()):
            da = int(m.group(1))
            mon_s = m.group(2)
            y = _coerce_year(int(m.group(3)))
            mon = MONTHS.get(mon_s)
            if not mon:
                continue
            try:
                add_candidate(0, base_idx + m.start(), date(y, mon, da))
            except ValueError:
                pass

    if not candidates:
        return None

    pri, idx, d = sorted(candidates, key=lambda t: (t[0], t[1], t[2].toordinal()))[0]
    return d.isoformat()


