        dec = Decimal(tok)
    except InvalidOperation:
        return None

    dec = dec.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    if dec < 0:
        return None
    return f"{dec:.2f}"


def extract_total_amount(text: str) -> str | None:
    text = _normalize_text(text)
    raw_lines = text.splitlines()
    lines = [ln.strip() for ln in raw_lines]
    upper_lines = [ln.upper() for ln in lines]

    def is_excluded(u: str) -> bool:
        return any(k in u for k in EXCLUSION_KEYWORDS)

    for group in PRIORITY_KEYWORD_GROUPS:
        for i, u in enumerate(upper_lines):
            if is_excluded(u):
                continue
            if not any(k in u for k in group):
                continue

            # same-line amount
            matches = list(_amount_pat.finditer(lines[i]))
            if matches:
                for m in reversed(matches):
                    val = _parse_amount_token(m.group(1))
                    if val is not None:
                        return val

            # next-line fallback
            if i + 1 < len(lines):
                nxt_u = upper_lines[i + 1]
                if not is_excluded(nxt_u):
                    matches = list(_amount_pat.finditer(lines[i + 1]))
                    if matches:
                        for m in reversed(matches):
                            val = _parse_amount_token(m.group(1))
                            if val is not None:
                                return val

    return None


def main():
    files = sorted([p for p in IMG_DIR.iterdir() if p.is_file() and p.suffix.lower() in IMAGE_EXTS], key=lambda p: p.name)
    if not files:
        raise SystemExit(f'No images found under {IMG_DIR}')

    rows: list[tuple[str, str | None, str | None]] = []

    for p in files:
        try:
            with Image.open(p) as im:
                im = im.convert('RGB')
                text = ocr_image(im)
        except Exception:
            rows.append((p.name, None, None))
            continue

        d = extract_date(text)
        t = extract_total_amount(text)
        rows.append((p.name, d, t))

    # Write xlsx (exactly one sheet)
    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    for fn, d, t in rows:
        ws.append([fn, d, t])

    # Ensure no extra sheets
    for s in list(wb.sheetnames):
        if s != 'results':
            del wb[s]

    OUT_PATH.parent.mkdir(parents=True, exist_ok=True)
    wb.save(OUT_PATH)

    # Post-write validation (oracle-aligned schema checks)
    wb2 = load_workbook(OUT_PATH)
    assert wb2.sheetnames == ['results'], f"Unexpected sheets: {wb2.sheetnames}"
    ws2 = wb2['results']

    headers = [ws2.cell(row=1, column=c).value for c in range(1, 4)]
    assert headers == ['filename', 'date', 'total_amount'], f"Bad headers: {headers}"

    # Collect rows (stop at first completely-empty row)
    out_rows = []
    for r in range(2, ws2.max_row + 1):
        vals = [ws2.cell(row=r, column=c).value for c in range(1, 4)]
        if vals == [None, None, None]:
            continue
        out_rows.append(vals)

    out_fns = [r[0] for r in out_rows]
    assert out_fns == sorted(out_fns), 'Rows are not sorted by filename'
    assert len(out_rows) == len(files), f"Row count mismatch: {len(out_rows)} vs {len(files)}"

    iso_pat = re.compile(r'^\d{4}-\d{2}-\d{2}$')
    amt_pat = re.compile(r'^\d+\.\d{2}$')

    for fn, d, t in out_rows:
        assert isinstance(fn, str) and fn, f"Bad filename cell: {fn!r}"
        if d is not None:
            assert isinstance(d, str) and iso_pat.match(d), f"Bad date for {fn}: {d!r}"
        if t is not None:
            assert isinstance(t, str) and amt_pat.match(t), f"Bad total for {fn}: {t!r}"

    print(f'Wrote {OUT_PATH} with {len(out_rows)} rows.')


if __name__ == '__main__':
    main()
